package com.northstarbank.core;import static org.junit.jupiter.api.Assertions.*;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.Base64;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import org.junit.jupiter.api.Test;
class ScopeTokenTest{private static final String KEY="01234567890123456789012345678901";private final ScopeToken tokens=new ScopeToken(KEY);@Test void branchScopeCannotCrossBranches()throws Exception{var c=tokens.verify("Bearer "+mint("EMP001|CSR|B01|0|"+Instant.now().plusSeconds(60).getEpochSecond()));tokens.require(c,"B01");assertThrows(ScopeToken.OutOfScope.class,()->tokens.require(c,"B02"));}@Test void regionScopeIncludesOnlyItsBranches()throws Exception{var c=tokens.verify("Bearer "+mint("EMP004|REGIONAL_MANAGER|R1|25000|"+Instant.now().plusSeconds(60).getEpochSecond()));tokens.require(c,"B03");assertThrows(ScopeToken.OutOfScope.class,()->tokens.require(c,"B04"));}private String mint(String body)throws Exception{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(KEY.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(body.getBytes(StandardCharsets.UTF_8))+"."+Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal(body.getBytes(StandardCharsets.UTF_8)));}}
